CREATE TABLE storage_objects (id TEXT PRIMARY KEY,physical_key TEXT,size INTEGER);
CREATE TABLE storage_entries (id TEXT PRIMARY KEY,instance_id TEXT,object_id TEXT,path TEXT,kind TEXT);
